1	import { useState, useRef, useEffect, useMemo } from 'react';
2	import type { LabelEvent } from '../../types/LabelEvent';
3	import type { LabelSpan, SpanKind } from '../../types/LabelSpan';
4	import type { Round } from '../../types/Round';
5	import { categoryForAction, colorForAction, iconForAction, matchFilter, formatFrameClock } from './taxonomy';
6	
7	const TL = { ruler: 26, round: 30, state: 30, span: 26, lane: 46, head: 132 };
8	
9	const SPAN_COLOR: Record<SpanKind, string> = {
10	  round: 'var(--green-500)',
11	  corner_swap: 'var(--purple-600)',
12	  excluded: 'var(--text-muted)',
13	};
14	
15	function useMeasure(): [React.RefObject<HTMLDivElement | null>, number] {
16	  const ref = useRef<HTMLDivElement>(null);
17	  const [w, setW] = useState(0);
18	  useEffect(() => {
19	    if (!ref.current) return;
20	    const ro = new ResizeObserver(es => { for (const e of es) setW(e.contentRect.width); });
21	    ro.observe(ref.current);
22	    return () => ro.disconnect();
23	  }, []);
24	  return [ref, w];
25	}
26	
27	function fmtSec(s: number): string {
28	  const m = Math.floor(s / 60);
29	  const sec = Math.floor(s % 60);
30	  return `${m}:${String(sec).padStart(2, '0')}`;
31	}
32	
33	function laneFor(e: LabelEvent): 'red' | 'blue' | null {
34	  if (e.corner === 0) return 'red';
35	  if (e.corner === 1) return 'blue';
36	  return null;
37	}
38	
39	interface Hover { e: LabelEvent; x: number; color: string }
40	
41	interface ClipProps {
42	  e: LabelEvent;
43	  x: number;
44	  color: string;
45	  flash: boolean;
46	  selected: boolean;
47	  onSeek: (frame: number) => void;
48	  onSelect: (id: number) => void;
49	  onHover: (h: Hover | null) => void;
50	}
51	
52	function Clip({ e, x, color, flash, selected, onSeek, onSelect, onHover }: ClipProps) {
53	  return (
54	    <button
55	      className="tl-clip"
56	      onPointerDown={ev => ev.stopPropagation()}
57	      onClick={ev => { ev.stopPropagation(); onSeek(e.frame); onSelect(e.id); }}
58	      onMouseEnter={ev => onHover({ e, x: (ev.currentTarget as HTMLElement).offsetLeft, color })}
59	      onMouseLeave={() => onHover(null)}
60	      title={selected ? `${e.description} · Delete to remove` : e.description}
61	      style={{
62	        position: 'absolute', left: x - 11, top: (TL.lane - 30) / 2, width: 22, height: 30, borderRadius: 7,
63	        display: 'grid', placeItems: 'center', cursor: 'pointer', zIndex: flash || selected ? 6 : 4, padding: 0,
64	        transition: 'transform .1s',
65	        border: `1px solid color-mix(in srgb, ${color} ${flash || selected ? 90 : 55}%, transparent)`,
66	        background: `color-mix(in srgb, ${color} ${flash || selected ? 34 : 18}%, var(--surface-inner))`,
67	        boxShadow: selected ? `0 0 0 2px #fff, 0 0 0 3.5px ${color}` : flash ? `0 0 0 1.5px ${color}, 0 0 16px -2px ${color}` : 'none',
68	        animation: 'feed-in .25s ease-out',
69	      }}
70	    >
71	      <span className="material-symbols-outlined" style={{ fontSize: 16, color }}>{iconForAction(e.action)}</span>
72	    </button>
73	  );
74	}
75	
76	interface AnnotationTimelineProps {
77	  events: LabelEvent[];
78	  spans: LabelSpan[];
79	  rounds: Round[];
80	  duration: number;
81	  fps: number;
82	  currentFrame: number;
83	  onSeek: (frame: number) => void;
84	  onSetPlaying: (playing: boolean) => void;
85	  onUpdateSpan: (id: number, patch: { start_frame?: number; end_frame?: number }) => void;
86	  onDeleteSpan: (id: number) => void;
87	  flashId: number | null;
88	  selectedEventId: number | null;
89	  onSelectEvent: (id: number | null) => void;
90	  filter: string;
91	  redName: string;
92	  blueName: string;
93	}
94	
95	export default function AnnotationTimeline({
96	  events, spans, rounds, duration, fps, currentFrame, onSeek, onSetPlaying, onUpdateSpan, onDeleteSpan,
97	  flashId, selectedEventId, onSelectEvent, filter, redName, blueName,
98	}: AnnotationTimelineProps) {
99	  const [zoom, setZoom] = useState(1);
100	  const [hover, setHover] = useState<Hover | null>(null);
101	  const [scrollRef, scrollW] = useMeasure();
102	  const draggingRef = useRef(false);
103	
104	  const time = (currentFrame - 1) / fps;
105	  const frameFor = (t: number) => Math.max(1, Math.round(t * fps) + 1);
106	  const xFor = (frame: number) => ((frame - 1) / fps) * pxPerSec;
107	
108	  const fitPx = scrollW > 0 ? scrollW / Math.max(duration, 1) : 2.2;
109	  const pxPerSec = fitPx * zoom;
110	  const W = duration * pxPerSec;
111	  const spansTop = TL.ruler + TL.round + TL.state;
112	  const lanesTop = spansTop + TL.span * 2;
113	  const totalH = lanesTop + TL.lane * 2;
114	  const boxH = totalH + 14;
115	
116	  // Live edge being dragged, so the block redraws smoothly before the PUT commits.
117	  const dragRef = useRef<{ id: number; edge: 'start' | 'end' } | null>(null);
118	  const [dragFrame, setDragFrame] = useState<number | null>(null);
119	
120	  const fil = (e: LabelEvent) => matchFilter(categoryForAction(e.action), filter);
121	  const redEv = events.filter(e => laneFor(e) === 'red' && e.action !== 'fight_end' && fil(e));
122	  const blueEv = events.filter(e => laneFor(e) === 'blue' && e.action !== 'fight_end' && fil(e));
123	  const roundEv = events.filter(e => categoryForAction(e.action) === 'round' || e.action === 'fight_end');
124	  // Everything after fight_end is dead air (celebration, doctor check, corner
125	  // talk) — the round span and the last state segment are visually capped
126	  // here to end there, so the timeline actually looks like the fight is
127	  // over. The underlying round span's real end_frame is untouched (only the
128	  // auto-created `excluded` span makes the tail harmless for scoring/export
129	  // — see Annotate.tsx's confirmFightEnd); this is display-only.
130	  const fightEndFrame = events.find(e => e.action === 'fight_end')?.frame ?? null;
131	  const stateEv = useMemo(
132	    () => events.filter(e => categoryForAction(e.action) === 'state').sort((a, b) => a.frame - b.frame),
133	    [events],
134	  );
135	  const segs = stateEv
136	    .map((e, i) => {
137	      const rawT1 = i + 1 < stateEv.length ? (stateEv[i + 1].frame - 1) / fps : duration;
138	      const t1 = fightEndFrame != null ? Math.min(rawT1, (fightEndFrame - 1) / fps) : rawT1;
139	      return {
140	        id: e.id,
141	        t0: (e.frame - 1) / fps,
142	        t1,
143	        state: e.action === 'state_clinch' ? 'CLINCH' : e.action === 'state_ground' ? 'GROUND' : 'STRIKING',
144	      };
145	    })
146	    .filter(s => s.t1 >= s.t0); // drop a segment that starts entirely after fight_end
147	
148	  // Same display-only capping as the state segments above: the round block
149	  // that contains fight_end is drawn ending there instead of at its real
150	  // (now-stale) end_frame. Edge-drag still targets the real span by id, so
151	  // dragging the end handle still writes the true end_frame — it just
152	  // starts from the visually-capped position rather than the stale one.
153	  const roundSpans = spans
154	    .filter(s => s.kind === 'round')
155	    .map(s => (
156	      fightEndFrame != null && s.end_frame != null &&
157	      s.start_frame <= fightEndFrame && fightEndFrame < s.end_frame
158	        ? { ...s, end_frame: fightEndFrame }
159	        : s
160	    ));
161	  const cornerSwapSpans = spans.filter(s => s.kind === 'corner_swap');
162	  const excludedSpans = spans.filter(s => s.kind === 'excluded');
163	
164	  const targets = [5, 10, 15, 30, 60, 120, 180];
165	  const tickEvery = targets.find(s => s * pxPerSec >= 64) || 240;
166	  const ticks: number[] = [];
167	  for (let t = 0; t <= duration; t += tickEvery) ticks.push(t);
168	
169	  const scrubRef = useRef<(clientX: number) => void>(() => {});
170	  scrubRef.current = (clientX: number) => {
171	    const el = scrollRef.current;
172	    if (!el) return;
173	    const r = el.getBoundingClientRect();
174	    const t = (clientX - r.left + el.scrollLeft) / pxPerSec;
175	    onSeek(frameFor(Math.max(0, Math.min(duration, t))));
176	  };
177	  useEffect(() => {
178	    const move = (e: PointerEvent) => { if (draggingRef.current) scrubRef.current(e.clientX); };
179	    const up = () => { draggingRef.current = false; };
180	    window.addEventListener('pointermove', move);
181	    window.addEventListener('pointerup', up);
182	    return () => { window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', up); };
183	  }, []);
184	  const startScrub = (e: React.PointerEvent) => {
185	    draggingRef.current = true;
186	    onSetPlaying(false);
187	    onSelectEvent(null); // clicking the background/ruler deselects whatever clip was selected
188	    scrubRef.current(e.clientX);
189	  };
190	
191	  // Edge-drag for span blocks (round / corner_swap / excluded resize handles).
192	  useEffect(() => {
193	    const move = (e: PointerEvent) => {
194	      const d = dragRef.current;
195	      const el = scrollRef.current;
196	      if (!d || !el) return;
197	      const r = el.getBoundingClientRect();
198	      const t = (e.clientX - r.left + el.scrollLeft) / pxPerSec;
199	      setDragFrame(frameFor(Math.max(0, Math.min(duration, t))));
200	    };
201	    const up = () => {
202	      const d = dragRef.current;
203	      if (d && dragFrame != null) {
204	        onUpdateSpan(d.id, d.edge === 'start' ? { start_frame: dragFrame } : { end_frame: dragFrame });
205	      }
206	      dragRef.current = null;
207	      setDragFrame(null);
208	    };
209	    window.addEventListener('pointermove', move);
210	    window.addEventListener('pointerup', up);
211	    return () => { window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', up); };
212	    // eslint-disable-next-line react-hooks/exhaustive-deps
213	  }, [pxPerSec, duration, dragFrame]);
214	  const startEdgeDrag = (id: number, edge: 'start' | 'end') => (e: React.PointerEvent) => {
215	    e.stopPropagation();
216	    onSetPlaying(false);
217	    dragRef.current = { id, edge };
218	  };
219	
220	  useEffect(() => {
221	    const el = scrollRef.current;
222	    if (!el) return;
223	    const x = xFor(currentFrame);
224	    const L = el.scrollLeft;
225	    const R = L + el.clientWidth;
226	    if (x < L + 48 || x > R - 48) el.scrollLeft = x - el.clientWidth / 2;
227	    // eslint-disable-next-line react-hooks/exhaustive-deps
228	  }, [time, pxPerSec]);
229	
230	  const TrackHead = ({ h, children, top }: { h: number; children: React.ReactNode; top: number }) => (
231	    <div style={{
232	      position: 'absolute', top, left: 0, height: h, width: TL.head, display: 'flex', alignItems: 'center', gap: 8,
233	      padding: '0 12px', boxSizing: 'border-box', borderBottom: '1px solid var(--border-subtle)',
234	      borderRight: '1px solid var(--border-glass)', background: 'var(--surface-inner)',
235	    }}>{children}</div>
236	  );
237	
238	  const playX = xFor(currentFrame);
239	
240	  // A span block with draggable edges (round/corner_swap) or a plain block
241	  // with a delete button (corner_swap/excluded). `end_frame == null` means
242	  // the start/end toggle is still open — draw it running to the playhead.
243	  const SpanBlock = ({ s, top, h, deletable }: { s: LabelSpan; top: number; h: number; deletable: boolean }) => {
244	    const dragging = dragRef.current?.id === s.id;
245	    const start = dragging && dragRef.current?.edge === 'start' && dragFrame != null ? dragFrame : s.start_frame;
246	    const end = dragging && dragRef.current?.edge === 'end' && dragFrame != null
247	      ? dragFrame
248	      : s.end_frame ?? currentFrame;
249	    const open = s.end_frame == null;
250	    const x0 = xFor(Math.min(start, end));
251	    const w = Math.max(4, xFor(Math.max(start, end)) - x0);
252	    const c = SPAN_COLOR[s.kind];
253	    return (
254	      <div
255	        style={{
256	          position: 'absolute', top, left: x0, width: w, height: h, borderRadius: 5, zIndex: 3,
257	          background: `color-mix(in srgb, ${c} ${open ? 10 : 16}%, transparent)`,
258	          border: `1px solid color-mix(in srgb, ${c} ${open ? 55 : 38}%, transparent)`,
259	          borderStyle: open ? 'dashed' : 'solid',
260	          display: 'flex', alignItems: 'center', overflow: 'hidden',
261	        }}
262	        title={s.value ? `${s.kind} — ${s.value}` : s.kind}
263	      >
264	        <div
265	          onPointerDown={startEdgeDrag(s.id, 'start')}
266	          title="Drag to move the start"
267	          style={{
268	            position: 'absolute', left: -5, top: 0, width: 13, height: '100%', cursor: 'ew-resize', zIndex: 4,
269	            display: 'flex', alignItems: 'center', justifyContent: 'flex-end', paddingRight: 4,
270	          }}
271	        >
272	          <span style={{ width: 2, height: '55%', borderRadius: 1, background: `color-mix(in srgb, ${c} 70%, transparent)` }} />
273	        </div>
274	        {!open && (
275	          <div
276	            onPointerDown={startEdgeDrag(s.id, 'end')}
277	            title="Drag to move the end"
278	            style={{
279	              position: 'absolute', right: -5, top: 0, width: 13, height: '100%', cursor: 'ew-resize', zIndex: 4,
280	              display: 'flex', alignItems: 'center', justifyContent: 'flex-start', paddingLeft: 4,
281	            }}
282	          >
283	            <span style={{ width: 2, height: '55%', borderRadius: 1, background: `color-mix(in srgb, ${c} 70%, transparent)` }} />
284	          </div>
285	        )}
286	        {w > 30 && (
287	          <span style={{ fontSize: 9.5, fontWeight: 800, color: c, whiteSpace: 'nowrap', paddingLeft: 8, pointerEvents: 'none' }}>
288	            {s.kind === 'round' ? `R${s.value ?? ''}` : s.value ?? s.kind.toUpperCase()}{open ? '…' : ''}
289	          </span>
290	        )}
291	        {deletable && !open && (
292	          <button
293	            onPointerDown={ev => ev.stopPropagation()}
294	            onClick={ev => { ev.stopPropagation(); onDeleteSpan(s.id); }}
295	            title="Delete"
296	            style={{
297	              position: 'absolute', right: 2, top: '50%', transform: 'translateY(-50%)', width: 14, height: 14,
298	              borderRadius: 4, border: 'none', background: 'rgba(0,0,0,0.35)', color: c, cursor: 'pointer',
299	              display: 'grid', placeItems: 'center', padding: 0, zIndex: 5,
300	            }}
301	          >
302	            <span className="material-symbols-outlined" style={{ fontSize: 10 }}>close</span>
303	          </button>
304	        )}
305	      </div>
306	    );
307	  };
308	
309	  return (
310	    <div style={{ display: 'flex', position: 'relative', height: boxH, borderRadius: 12, overflow: 'hidden', border: '1px solid var(--border-subtle)' }}>
311	      <div style={{ position: 'relative', width: TL.head, flexShrink: 0, background: 'var(--surface-inner)', zIndex: 8 }}>
312	        <div style={{
313	          position: 'absolute', top: 0, height: TL.ruler, width: TL.head, borderBottom: '1px solid var(--border-glass)',
314	          borderRight: '1px solid var(--border-glass)', display: 'flex', alignItems: 'center', padding: '0 12px',
315	          fontSize: 9, fontWeight: 800, letterSpacing: '0.1em', color: 'var(--text-disabled)',
316	        }}>TRACKS</div>
317	        <TrackHead top={TL.ruler} h={TL.round}>
318	          <span className="material-symbols-outlined" style={{ fontSize: 15, color: 'var(--green-500)' }}>flag</span>
319	          <span style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: '0.06em', color: 'var(--text-tertiary)' }}>ROUNDS</span>
320	        </TrackHead>
321	        <TrackHead top={TL.ruler + TL.round} h={TL.state}>
322	          <span className="material-symbols-outlined" style={{ fontSize: 15, color: 'var(--slate-400)' }}>change_circle</span>
323	          <span style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: '0.06em', color: 'var(--text-tertiary)' }}>STATE</span>
324	        </TrackHead>
325	        <TrackHead top={spansTop} h={TL.span}>
326	          <span className="material-symbols-outlined" style={{ fontSize: 14, color: 'var(--purple-600)' }}>swap_horiz</span>
327	          <span style={{ fontSize: 10, fontWeight: 800, letterSpacing: '0.05em', color: 'var(--text-tertiary)' }}>CORNER SWAP</span>
328	        </TrackHead>
329	        <TrackHead top={spansTop + TL.span} h={TL.span}>
330	          <span className="material-symbols-outlined" style={{ fontSize: 14, color: 'var(--text-muted)' }}>visibility_off</span>
331	          <span style={{ fontSize: 10, fontWeight: 800, letterSpacing: '0.05em', color: 'var(--text-tertiary)' }}>EXCLUDED</span>
332	        </TrackHead>
333	        <TrackHead top={lanesTop} h={TL.lane}>
334	          <span style={{ width: 9, height: 9, borderRadius: 2, background: 'var(--f-red)' }} />
335	          <span style={{ fontSize: 12, fontWeight: 800, color: 'var(--text-secondary)' }}>{redName}</span>
336	        </TrackHead>
337	        <TrackHead top={lanesTop + TL.lane} h={TL.lane}>
338	          <span style={{ width: 9, height: 9, borderRadius: 2, background: 'var(--f-blue)' }} />
339	          <span style={{ fontSize: 12, fontWeight: 800, color: 'var(--text-secondary)' }}>{blueName}</span>
340	        </TrackHead>
341	      </div>
342	
343	      <div ref={scrollRef} className="tl-scroll" style={{ flex: 1, overflowX: 'auto', overflowY: 'hidden', position: 'relative' }}>
344	        <div style={{ position: 'relative', width: W, height: totalH, minWidth: '100%' }}>
345	          <div style={{ position: 'absolute', top: TL.ruler, left: 0, width: '100%', height: TL.round, background: 'rgba(255,255,255,0.018)' }} />
346	          <div style={{ position: 'absolute', top: lanesTop + TL.lane, left: 0, width: '100%', height: TL.lane, background: 'rgba(255,255,255,0.022)' }} />
347	
348	          {rounds.map(r => (
349	            <div key={'rb' + r.id}>
350	              {r.round_number > 1 && (
351	                <div style={{ position: 'absolute', top: TL.ruler, left: xFor(r.start_frame), width: 1, height: totalH - TL.ruler, background: 'rgba(255,255,255,0.12)' }} />
352	              )}
353	            </div>
354	          ))}
355	
356	          <div
357	            onPointerDown={startScrub}
358	            className="tl-ruler"
359	            style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: TL.ruler, cursor: 'ew-resize', borderBottom: '1px solid var(--border-glass)' }}
360	          >
361	            {ticks.map(t => (
362	              <div key={t} style={{ position: 'absolute', left: t * pxPerSec, top: 0, height: '100%', pointerEvents: 'none' }}>
363	                <div style={{ position: 'absolute', left: 0, bottom: 0, width: 1, height: 7, background: 'rgba(255,255,255,0.22)' }} />
364	                <span style={{ position: 'absolute', left: 5, top: 5, fontSize: 10, fontWeight: 700, color: 'var(--text-muted)', fontVariantNumeric: 'tabular-nums' }}>{fmtSec(t)}</span>
365	              </div>
366	            ))}
367	          </div>
368	
369	          <div onPointerDown={startScrub} style={{ position: 'absolute', top: TL.ruler, left: 0, width: '100%', height: totalH - TL.ruler, cursor: 'ew-resize', zIndex: 1 }} />
370	
371	          {roundSpans.map(s => (
372	            <SpanBlock key={'rs' + s.id} s={s} top={TL.ruler + 4} h={TL.round - 8} deletable />
373	          ))}
374	
375	          {segs.map(s => {
376	            const c = s.state === 'GROUND' ? 'var(--f-red)' : s.state === 'CLINCH' ? 'var(--orange-400)' : 'var(--accent)';
377	            const w = Math.max(2, s.t1 * pxPerSec - s.t0 * pxPerSec);
378	            return (
379	              <div
380	                key={'seg' + s.id}
381	                title={s.state}
382	                style={{
383	                  position: 'absolute', top: TL.ruler + TL.round + 5, left: s.t0 * pxPerSec, width: w, height: TL.state - 10,
384	                  borderRadius: 6, zIndex: 2, background: `color-mix(in srgb, ${c} 16%, transparent)`,
385	                  border: `1px solid color-mix(in srgb, ${c} 38%, transparent)`, borderLeft: `3px solid ${c}`,
386	                  overflow: 'hidden', display: 'flex', alignItems: 'center', paddingLeft: 8,
387	                }}
388	              >
389	                {w > 64 && <span style={{ fontSize: 10, fontWeight: 800, letterSpacing: '0.05em', color: c, whiteSpace: 'nowrap' }}>{s.state}</span>}
390	              </div>
391	            );
392	          })}
393	
394	          {cornerSwapSpans.map(s => (
395	            <SpanBlock key={'cs' + s.id} s={s} top={spansTop + 3} h={TL.span - 6} deletable />
396	          ))}
397	          {excludedSpans.map(s => (
398	            <SpanBlock key={'ex' + s.id} s={s} top={spansTop + TL.span + 3} h={TL.span - 6} deletable />
399	          ))}
400	
401	          {roundEv.map(e => {
402	            const fe = e.action === 'fight_end';
403	            const c = colorForAction(e.action);
404	            const selected = e.id === selectedEventId;
405	            return (
406	              <button
407	                key={'rp' + e.id}
408	                className="tl-clip"
409	                onPointerDown={ev => ev.stopPropagation()}
410	                onClick={ev => { ev.stopPropagation(); onSeek(e.frame); onSelectEvent(e.id); }}
411	                onMouseEnter={ev => setHover({ e, x: (ev.currentTarget as HTMLElement).offsetLeft, color: c })}
412	                onMouseLeave={() => setHover(null)}
413	                title={selected ? `${e.description} · Delete to remove` : e.description}
414	                style={{
415	                  position: 'absolute', top: TL.ruler + 5, left: xFor(e.frame) - 10, width: 20, height: TL.round - 10,
416	                  borderRadius: 6, zIndex: selected ? 6 : 5, display: 'grid', placeItems: 'center', cursor: 'pointer', padding: 0,
417	                  border: `1px solid color-mix(in srgb, ${c} 60%, transparent)`,
418	                  background: `color-mix(in srgb, ${c} ${fe ? 30 : 18}%, var(--surface-inner))`,
419	                  boxShadow: selected ? `0 0 0 2px #fff, 0 0 0 3.5px ${c}` : e.id === flashId ? `0 0 0 1.5px ${c}, 0 0 14px -2px ${c}` : 'none',
420	                }}
421	              >
422	                <span className="material-symbols-outlined" style={{ fontSize: 14, color: c }}>{iconForAction(e.action)}</span>
423	              </button>
424	            );
425	          })}
426	
427	          {redEv.map(e => (
428	            <div key={e.id} style={{ position: 'absolute', top: lanesTop, left: 0 }}>
